style.css:
/* Set Black Background and White Text */
body {
    background-color: #000000; /* Black background */
    color: #FFFFFF; /* White text */
}

/* Set Bamboo Green for Regular Hyperlinks */
a {
    color: #7CFC00; /* Bamboo Green */
}

/* Set Light Crimson Red for Hover and Active States of Hyperlinks */
a:hover, a:active {
    color: #DC143C; /* Light Crimson Red */
}
